SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",      ih.INVC_ID                                            AS \"Invoice ID\",     ih.INVC_TYPE                                          AS \"Invoice Type Code\",     CASE ih.INVC_TYPE         WHEN 'PP'  THEN 'Purchase Order Invoice'         WHEN 'RC'  THEN 'RTV Credit Note'         WHEN 'CO'  THEN 'Consignment Invoice'         WHEN 'DL'  THEN 'Deal Invoice'         WHEN 'OB'  THEN 'Obligation Invoice'         WHEN 'NM'  THEN 'Non-Merchandise Invoice'         WHEN 'CD'  THEN 'Credit Note'         WHEN 'CR'  THEN 'Credit Note Request'         WHEN 'DM'  THEN 'Debit Memo'         ELSE ih.INVC_TYPE     END                                                   AS \"Invoice Type Description\",     ih.INVC_DATE                                          AS \"Invoice Date\",     ih.EXT_REF_NO                                         AS \"Vendor Document Number\",      TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE)                  AS \"Days Since Invoice\",     CASE         WHEN TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) BETWEEN 0  AND 7         THEN '0 - 7 Days'         WHEN TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) BETWEEN 8  AND 15         THEN '8 - 15 Days'         WHEN TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) BETWEEN 16 AND 30         THEN '16 - 30 Days'         ELSE '30+ Days'     END                                                   AS \"Aging Bucket\",      ih.SUPPLIER                                           AS \"Supplier ID\",     sp.SUP_NAME                                           AS \"Supplier Name\",     sp.SUP_STATUS                                         AS \"Supplier Status\",     ih.PARTNER_ID                                         AS \"Partner ID\",     pt.PARTNER_DESC                                       AS \"Partner Name\",      ix.ORDER_NO                                           AS \"PO Number\",     oh.STATUS                                             AS \"PO Status Code\",     CASE oh.STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE oh.STATUS     END                                                   AS \"PO Status Description\",     ix.LOCATION                                           AS \"Location ID\",     ix.LOC_TYPE                                           AS \"Location Type\",     CASE ix.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS \"Location Name\",      ih.TOTAL_MERCH_COST                                   AS \"Total Invoice Amount\",     ih.CURRENCY_CODE                                      AS \"Invoice Currency\",     ih.EXCHANGE_RATE                                      AS \"Exchange Rate\",     ROUND(ih.TOTAL_MERCH_COST * NVL(ih.EXCHANGE_RATE, 1), 2)                                                           AS \"Total Amount Local Currency\",     ih.TERMS                                              AS \"Payment Terms\",     ih.DUE_DATE                                           AS \"Payment Due Date\",      ih.EDI_SENT_IND                                       AS \"EDI Sent Indicator\",     ih.EDI_INVC_IND                                       AS \"EDI Invoice Indicator\",     CASE ih.EDI_SENT_IND         WHEN 'Y' THEN 'EDI Sent to ReIM'         WHEN 'N' THEN 'NOT YET SENT - EDI extract pending'         ELSE          'STATUS UNKNOWN'     END                                                   AS \"Extraction Status\",      ih.STATUS                                             AS \"Match Status Code\",     CASE ih.STATUS         WHEN 'U' THEN 'Unmatched'         WHEN 'M' THEN 'Matched'         WHEN 'C' THEN 'Closed'         WHEN 'A' THEN 'Auto-Match Pending'         WHEN 'E' THEN 'Error'         ELSE NVL(ih.STATUS, 'Not Set')     END                                                   AS \"Match Status Description\",     ih.MATCH_FAIL_IND                                     AS \"Match Fail Indicator\",     ih.MATCH_DATE                                         AS \"Match Date\",     ih.MATCH_ID                                           AS \"Match ID\",      CASE         WHEN NVL(ih.EDI_SENT_IND, 'N') = 'N'         THEN 'NOT SENT - EDI extract did not process'         WHEN ih.EDI_SENT_IND = 'Y'              AND ih.STATUS = 'E'         THEN 'EXTRACTION ERROR - ReIM rejected the invoice'         WHEN ih.EDI_SENT_IND = 'Y'              AND NVL(ih.STATUS, 'U') = 'U'         THEN 'SENT BUT UNMATCHED - Awaiting ReIM processing'         WHEN NVL(ih.MATCH_FAIL_IND, 'N') = 'Y'         THEN 'MATCH FAILURE - Invoice failed matching process'         ELSE 'UNKNOWN FAILURE - Review EDI and ReIM logs'     END                                                   AS \"Failure Category\",      ix.ID                                                 AS \"Cross Reference ID\",     ix.SHIPMENT                                           AS \"Linked Shipment Number\",      ih.PAID_IND                                           AS \"Paid Indicator\",     ih.FORCE_PAY_IND                                      AS \"Force Pay Indicator\",     ih.APPROVAL_DATE                                      AS \"Approval Date\",     ih.APPROVAL_ID                                        AS \"Approved By\",     ih.POST_DATE                                          AS \"Post Date\",     ih.PAYMENT_DATE                                       AS \"Payment Date\",     ih.PAYMENT_REF_NO                                     AS \"Payment Reference Number\",     ih.DIRECT_IND                                         AS \"Direct Indicator\",      id_cnt.LINE_COUNT                                     AS \"Invoice Line Count\",     id_cnt.TOTAL_LINE_AMOUNT                              AS \"Total Line Amount\",      nm_cnt.NON_MERCH_LINE_COUNT                           AS \"Non-Merchandise Line Count\",     nm_cnt.NON_MERCH_TOTAL_AMT                            AS \"Non-Merchandise Total Amount\",      ih.CREATE_DATE                                        AS invoice_create_date,     ih.CREATE_ID                                          AS invoice_created_by,      CASE         WHEN NVL(ih.EDI_SENT_IND, 'N') = 'N'         THEN 'Check edidlinv.pc Phase 4 batch log for errors; rerun or reprocess invoice'         WHEN ih.STATUS = 'E'         THEN 'Review ReIM IM_REJECTIONS for error detail; correct invoice and resubmit'         WHEN NVL(ih.STATUS, 'U') = 'U'              AND TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE) &gt; 15         THEN 'Invoice aged &gt;15 days unmatched - escalate to AP team for manual match'         WHEN NVL(ih.MATCH_FAIL_IND, 'N') = 'Y'         THEN 'Clear match failure flag; may require ReIM team intervention'         ELSE 'Review edidlinv.pc and ReIM logs; verify invoice staging data is complete'     END                                                   AS \"Recommended Action\"  FROM     MFCS_RDS.RDS_WV_INVC_HEAD                  ih      LEFT JOIN MFCS_RDS.RDS_WV_INVC_XREF        ix    ON  ih.INVC_ID     = ix.INVC_ID      LEFT JOIN MFCS_RDS.RDS_WV_ORDHEAD           oh    ON  ix.ORDER_NO   = oh.ORDER_NO      LEFT JOIN MFCS_RDS.RDS_WV_SUPS              sp    ON  ih.SUPPLIER   = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_PARTNER           pt    ON  ih.PARTNER_ID = pt.PARTNER_ID      LEFT JOIN MFCS_RDS.RDS_WV_STORE             st    ON  ix.LOCATION   = st.STORE                                                       AND ix.LOC_TYPE   = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH               wh     ON  ix.LOCATION   = wh.WH                                                       AND ix.LOC_TYPE   = 'W'      LEFT JOIN (

