\":false},{\"prepColumnName\":\"Recommended Action\",\"isUserCalculation\":false}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Invoice ID\"],\"expressionSourceColumns\":[\"Invoice ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Invoice ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Invoice ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null},{\"id\":\"2\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"1\"},{\"id\":\"3\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"PO Number\"],\"expressionSourceColumns\":[\"PO Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"PO Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"PO Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"2\"},{\"id\":\"4\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Cross Reference ID\"],\"expressionSourceColumns\":[\"Cross Reference ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Cross Reference ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Cross Reference ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"},{\"id\":\"6\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Linked Shipment Number\"],\"expressionSourceColumns\":[\"Linked Shipment Number\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Linked Shipment Number\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Linked Shipment Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"5\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT\\n            id.INVC_ID,\\n            COUNT(*)                                      AS line_count,\\n            ROUND(SUM(id.INVC_UNIT_COST * id.INVC_QTY), 2) AS total_line_amount\\n        FROM  MFCS_RDS.RDS_WV_INVC_DETAIL        id\\n        GROUP BY id.INVC_ID\\n    ) id_cnt                                              ON  ih.INVC_ID = id_cnt.INVC_ID\\n\\n    LEFT JOIN (\\n

-- ── Query 5 ────────────────────────────────────────────────────────────
SELECT\\n            nm.INVC_ID,\\n            COUNT(*)                                      AS non_merch_line_count,\\n            ROUND(SUM(nm.NON_MERCH_AMT), 2)              AS non_merch_total_amt\\n        FROM  MFCS_RDS.RDS_WV_INVC_NON_MERCH     nm\\n        GROUP BY nm.INVC_ID\\n    ) nm_cnt                                              ON  ih.INVC_ID = nm_cnt.INVC_ID\\n\\nWHERE\\n    (\\n        NVL(ih.EDI_SENT_IND, 'N') = 'N'\\n        OR NVL(ih.STATUS, 'U') NOT IN ('M','C')\\n        OR NVL(ih.MATCH_FAIL_IND, 'N') = 'Y'\\n    )\\n    AND ih.INVC_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n\\nORDER BY\\n    (TRUNC(SYSDATE) - TRUNC(ih.INVC_DATE)) DESC,\\n    CASE\\n        WHEN NVL(ih.EDI_SENT_IND,'N') = 'N'\\n        THEN 'NOT SENT - EDI extract did not process'\\n        WHEN ih.STATUS = 'E'\\n        THEN 'EXTRACTION ERROR - ReIM rejected the invoice'\\n        WHEN NVL(ih.STATUS,'U') = 'U'\\n        THEN 'SENT BUT UNMATCHED - Awaiting ReIM processing'\\n        ELSE 'MATCH FAILURE'\\n    END,\\n    ih.TOTAL_MERCH_COST DESC,\\n    sp.SUP_NAME,\\n    ih.INVC_ID;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-14T16:47:10.147+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_055_Failed_Inject_Invoices'","parent-namespace":"ReCommon","parent-name":"RPT_055_Failed_Inject_Invoices","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_055_Failed_Inject_Invoices'"}
